```json
{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_deployment_name dep, count(DISTINCT attr_k8s_pod_name) pods, max(time) last_t FROM abnormal_metrics WHERE attr_k8s_deployment_name IN ('profile') GROUP BY 1",
          "claim": "In the abnormal window the profile deployment has zero pods reporting metrics; normal had one pod up to about 11:50:35."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, count(*) n, min(time) t0, max(time) t1, min(value) vmin, max(value) vmax FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'profile-%' GROUP BY ALL",
          "claim": "profile pod restart counter climbed from 3 to 6 before the pod stopped reporting around 11:54:45."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name='profile.Profile/GetProfiles' GROUP BY ALL",
          "claim": "Frontend's GetProfiles client calls to profile fail with Error status (1017 spans); profile emits no server spans in the abnormal window."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY ALL",
          "claim": "Frontend logs 'Get profiles failed' ERROR 1140 times from 11:50:54 onward, the only error message in the abnormal window."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('profile.Profile/GetProfiles','HTTP /hotels','HTTP /recommendations') GROUP BY ALL",
          "claim": "Profile call failures propagate into frontend HTTP /hotels and /recommendations server spans returning Error status."
        }
      ]
    }
  ]
}
```

